import solution

def test_basic():
    assert solution.normalize_name('  Hello   WORLD  ') == 'hello-world', solution.normalize_name('  Hello   WORLD  ')

def test_strip_hyphens():
    assert solution.normalize_name('--edge--case--') == 'edge-case', solution.normalize_name('--edge--case--')

def test_single():
    assert solution.normalize_name('A  B') == 'a-b', solution.normalize_name('A  B')

try:
    test_basic()
    test_strip_hyphens()
    test_single()
except AssertionError as exc:
    print(f'FAILED: {exc}')
    raise SystemExit(1)
print('OK')

import solution

def test_two_rows():
    assert solution.total_value('widget,2,3.50\ngadget,1,10.00\n') == 17.0, solution.total_value('widget,2,3.50\ngadget,1,10.00\n')

def test_blank_lines():
    assert solution.total_value('') == 0.0, solution.total_value('')

def test_rounding():
    assert abs(solution.total_value('a,3,0.1\n') - 0.3) < 1e-9, solution.total_value('a,3,0.1\n')

try:
    test_two_rows()
    test_blank_lines()
    test_rounding()
except AssertionError as exc:
    print(f'FAILED: {exc}')
    raise SystemExit(1)
print('OK')

import solution

def test_nested():
    assert solution.is_balanced('([]{})') is True, solution.is_balanced('([]{})')

def test_interleaved():
    assert solution.is_balanced('([)]') is False, solution.is_balanced('([)]')

def test_unclosed():
    assert solution.is_balanced('(((') is False, solution.is_balanced('(((')

def test_empty():
    assert solution.is_balanced('') is True, solution.is_balanced('')

try:
    test_nested()
    test_interleaved()
    test_unclosed()
    test_empty()
except AssertionError as exc:
    print(f'FAILED: {exc}')
    raise SystemExit(1)
print('OK')
